-- suite test: t_zork (auto-generated by hand, shared boilerplate)
local frame = 0
local t = 0
local function inject(keys)
  for i = 1, #keys do
    emu.write16(0x7E0700 + t, 0x1000 + keys:byte(i), emu.memType.snesMemory)
    t = (t + 2) % 64
  end
  emu.write16(0x7E00D8, t, emu.memType.snesMemory)
end
local function bufhas(str)
  for r = 0, 24 do
    local s = ""
    for c = 0, 79 do
      local ch = emu.read(0x7E1000 + r*160 + c*2, emu.memType.snesMemory)
      if ch < 32 or ch > 126 then ch = 32 end
      s = s .. string.char(ch)
    end
    if s:find(str, 1, true) then return true end
  end
  return false
end
local function bufbyte2(b1, b2)
  for r = 0, 24 do
    for c = 0, 78 do
      if emu.read(0x7E1000 + r*160 + c*2, emu.memType.snesMemory) == b1 and
         emu.read(0x7E1000 + r*160 + (c+1)*2, emu.memType.snesMemory) == b2 then
        return true
      end
    end
  end
  return false
end
local function booted()
  return bufhas("C:\\>")
end

-- Adaptive: advance on what's on screen, not fixed frame numbers, so it can't
-- break when headless emulation speed varies. Loads Zork, then exercises input
-- (open mailbox -> leaflet).
local stage = 0
emu.addEventCallback(function()
  frame = frame + 1
  if stage == 0 and frame > 900 and frame % 30 == 0 and booted() then
    inject("zork1\r"); stage = 1
  elseif stage == 1 and frame % 30 == 0 and bufhas("mailbox") then
    inject("open mailbox\r"); stage = 2
  elseif stage == 2 and frame % 20 == 0 and bufhas("leaflet") then
    print("RESULT PASS t_zork"); emu.stop(0)
  end
  if frame == 16000 then print("RESULT FAIL t_zork"); emu.stop(0) end
end, emu.eventType.endFrame)
